D=Path('cvpr2027/data');T=Path('cvpr2027/tmp/cad-fem-transmission-search');names=['web-cad-fem-spur-gear-pair','web-cad-fem-ventilated-rotor','web-cad-fem-finned-heatsink','web-cad-fem-nx-heatsink','web-cad-fem-titanium-forming-held','web-cad-fem-crane-drawings-held'];G,R,H,N,F,C=[D/n for n in names]
